
import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { Form, Link, useFetcher, useNavigation, useSearchParams } from "react-router";

import { actionErrorMessage } from "~/lib/action-error.server";
import { MetricCard, StatusBadge } from "~/components/dashboard/layout/DashboardPageLayout";
import { EmptyState, ErrorBanner, primaryButtonClass } from "~/components/dashboard/section";
import { TaskIssueKind, TaskIssueStatus, TaskMilestoneStatus, UserStudioRole, isTaskOpen, taskKindLabel, taskStatusLabel, type ProjectDto, type StudioMemberDto, type TaskCommentDto, type TaskIssueDetailDto, type TaskIssueDto, type TaskIssueFilters, type TaskLabelDto, type TaskMilestoneDto, type Workspace } from "~/lib/api";
import { ApiError, createTask, createTaskComment, createTaskLabel, createTaskMilestone, deleteTask, deleteTaskComment, deleteTaskLabel, deleteTaskMilestone, getTask, listProjects, listStudioMembers, listTaskLabels, listTaskMilestones, listTasks, updateTask, updateTaskComment, updateTaskLabel, updateTaskMilestone, updateTaskStatus } from "~/lib/api.server";
import { requireUser } from "~/lib/auth.server";
import { createRequestLogger, withUser } from "~/lib/logger.server";
import { getSession } from "~/lib/session.server";

import { requireStudioAccess } from "./access.server";
import type { Route } from "./+types/tasks";

export function meta() { return [{ title: "Studio tasks - Kuvox" }]; }

const studioWs = (studioId: string): Workspace => ({ kind: "studio", studioId });
const statuses = [TaskIssueStatus.Open, TaskIssueStatus.InProgress, TaskIssueStatus.InReview, TaskIssueStatus.ChangesRequested, TaskIssueStatus.Approved, TaskIssueStatus.Done, TaskIssueStatus.Closed];
const lanes: { title: string; statuses: number[]; color: string }[] = [
  { title: "Open", statuses: [TaskIssueStatus.Open], color: "#5B6CFF" },
  { title: "Active", statuses: [TaskIssueStatus.InProgress, TaskIssueStatus.InReview], color: "#0EA5A4" },
  { title: "Needs action", statuses: [TaskIssueStatus.ChangesRequested], color: "#D97706" },
  { title: "Done", statuses: [TaskIssueStatus.Approved, TaskIssueStatus.Done, TaskIssueStatus.Closed], color: "#16A34A" },
];

export async function loader({ request, params }: Route.LoaderArgs) {
  const log = createRequestLogger(request);
  const user = await requireUser(request, log);
  const reqLog = withUser(log, user);
  const session = await getSession(request);
  const accessToken = session.get("accessToken");
  const studioId = params.studioId;
  const url = new URL(request.url);
  const filters = filtersFromSearch(url.searchParams);
  const taskId = url.searchParams.get("taskId");
  const section = sectionFromSearch(url.searchParams);
  if (!accessToken) return emptyLoader(filters, user.id, "Your session expired. Please sign in again.");

  try {
    const access = await requireStudioAccess(accessToken, studioId, reqLog);
    const [items, allItems, milestones, labels, members, projects, taskDetail] = await Promise.all([
      listTasks(accessToken, studioId, filters, reqLog),
      listTasks(accessToken, studioId, {}, reqLog),
      listTaskMilestones(accessToken, studioId, reqLog),
      listTaskLabels(accessToken, studioId, reqLog),
      listStudioMembers(accessToken, studioId, reqLog),
      listProjects(accessToken, studioWs(studioId), reqLog),
      taskId ? getTask(accessToken, taskId, reqLog) : Promise.resolve(null),
    ]);
    return { items, allItems, milestones, labels, members, projects: projects.items, taskDetail, filters, section, selectedTaskId: taskId, currentUserId: user.id, canWrite: access.canWriteContent, canModerateComments: access.role === UserStudioRole.Owner || access.role === UserStudioRole.Admin, error: null as string | null };
  } catch (error) {
    if (error instanceof Response) throw error;
    const message = error instanceof ApiError ? error.message : "Couldn't load Studio tasks.";
    reqLog.error({ err: error, studioId }, "failed to load studio tasks");
    return emptyLoader(filters, user.id, message);
  }
}

export async function action({ request, params }: Route.ActionArgs) {
  const log = createRequestLogger(request);
  const user = await requireUser(request, log);
  const reqLog = withUser(log, user);
  const session = await getSession(request);
  const accessToken = session.get("accessToken");
  if (!accessToken) return { error: "Your session expired. Please sign in again." };
  const studioId = params.studioId;
  const formData = await request.formData();
  const intent = String(formData.get("intent") ?? "");
  try {
    await requireStudioAccess(accessToken, studioId, reqLog);
    if (intent === "createTask" || intent === "createSubtask") {
      const title = String(formData.get("title") ?? "").trim();
      if (!title) return { error: "Give the task a title." };
      const task = await createTask(accessToken, studioId, taskPayload(formData, title), reqLog);
      return { ok: true, intent, taskId: task.id };
    }
    if (intent === "updateTask") {
      const id = String(formData.get("id") ?? ""); const title = String(formData.get("title") ?? "").trim();
      if (!id || !title) return { error: "Task and title are required." };
      await updateTask(accessToken, id, updatePayload(formData, title), reqLog);
      return { ok: true, intent, taskId: id };
    }
    if (intent === "deleteTask") { const id = String(formData.get("id") ?? ""); if (id) await deleteTask(accessToken, id, reqLog); return { ok: true, intent, taskId: optionalString(formData.get("taskId")) ?? id }; }
    if (intent === "status") { const id = String(formData.get("id") ?? ""); if (id) await updateTaskStatus(accessToken, id, Number(formData.get("status") ?? TaskIssueStatus.Open), reqLog); return { ok: true, intent, taskId: id }; }
    if (intent === "createMilestone" || intent === "updateMilestone") {
      const id = String(formData.get("id") ?? ""); const title = String(formData.get("title") ?? "").trim();
      if (!title) return { error: "Milestone title is required." };
      const body = { title, description: optionalString(formData.get("description")), dueDate: optionalString(formData.get("dueDate")), status: Number(formData.get("status") ?? TaskMilestoneStatus.Open) };
      if (intent === "createMilestone") await createTaskMilestone(accessToken, studioId, body, reqLog); else await updateTaskMilestone(accessToken, id, body, reqLog);
      return { ok: true, intent };
    }
    if (intent === "deleteMilestone") { const id = String(formData.get("id") ?? ""); if (id) await deleteTaskMilestone(accessToken, id, reqLog); return { ok: true, intent }; }
    if (intent === "createLabel" || intent === "updateLabel") {
      const id = String(formData.get("id") ?? ""); const name = String(formData.get("name") ?? "").trim();
      if (!name) return { error: "Label name is required." };
      const body = { name, color: String(formData.get("color") ?? "#5B6CFF") };
      if (intent === "createLabel") await createTaskLabel(accessToken, studioId, body, reqLog); else await updateTaskLabel(accessToken, id, body, reqLog);
      return { ok: true, intent };
    }
    if (intent === "deleteLabel") { const id = String(formData.get("id") ?? ""); if (id) await deleteTaskLabel(accessToken, id, reqLog); return { ok: true, intent }; }
    if (intent === "createComment") { const taskId = String(formData.get("taskId") ?? ""); const body = String(formData.get("body") ?? "").trim(); if (!taskId || !body) return { error: "Comment is required." }; await createTaskComment(accessToken, taskId, { body }, reqLog); return { ok: true, intent, taskId }; }
    if (intent === "updateComment") { const id = String(formData.get("id") ?? ""); const taskId = String(formData.get("taskId") ?? ""); const body = String(formData.get("body") ?? "").trim(); if (!id || !body) return { error: "Comment is required." }; await updateTaskComment(accessToken, id, { body }, reqLog); return { ok: true, intent, taskId }; }
    if (intent === "deleteComment") { const id = String(formData.get("id") ?? ""); const taskId = String(formData.get("taskId") ?? ""); if (id) await deleteTaskComment(accessToken, id, reqLog); return { ok: true, intent, taskId }; }
    return { error: "Unknown action." };
  } catch (error) {
    if (error instanceof Response) throw error;
    const message = actionErrorMessage(error); reqLog.error({ err: error, intent, studioId, userId: user.id }, "studio task action failed"); return { error: message, intent };
  }
}

function emptyLoader(filters: ReturnType<typeof filtersFromSearch>, currentUserId: string, error: string | null) { return { items: [] as TaskIssueDto[], allItems: [] as TaskIssueDto[], milestones: [] as TaskMilestoneDto[], labels: [] as TaskLabelDto[], members: [] as StudioMemberDto[], projects: [] as ProjectDto[], taskDetail: null as TaskIssueDetailDto | null, filters, section: "board" as const, selectedTaskId: null as string | null, currentUserId, canWrite: false, canModerateComments: false, error }; }
function filtersFromSearch(search: URLSearchParams): TaskIssueFilters & { kind: string; status: string; q: string } { return { kind: search.get("kind") ?? "", status: search.get("status") ?? "", assigneeId: search.get("assigneeId") ?? "", milestoneId: search.get("milestoneId") ?? "", labelId: search.get("labelId") ?? "", projectId: search.get("projectId") ?? "", q: search.get("q") ?? "" }; }
function sectionFromSearch(search: URLSearchParams): "board" | "milestones" | "labels" { const section = search.get("section"); return section === "milestones" || section === "labels" ? section : "board"; }
function taskPayload(formData: FormData, title: string) { return { ...baseTaskPayload(formData, title, TaskIssueKind.Task), assigneeIds: formData.getAll("assigneeIds").map(String).filter(Boolean), reviewerIds: formData.getAll("reviewerIds").map(String).filter(Boolean) }; }
function reviewPayload(formData: FormData, title: string) { return { ...baseTaskPayload(formData, title, TaskIssueKind.Review), assigneeIds: [], reviewerIds: formData.getAll("reviewerIds").map(String).filter(Boolean) }; }
function updatePayload(formData: FormData, title: string) { return Number(formData.get("kind") ?? TaskIssueKind.Task) === TaskIssueKind.Review ? reviewPayload(formData, title) : taskPayload(formData, title); }
function baseTaskPayload(formData: FormData, title: string, kind: number) { return { kind, title, description: optionalString(formData.get("description")), dueDate: optionalString(formData.get("dueDate")), milestoneId: optionalString(formData.get("milestoneId")), projectId: optionalString(formData.get("projectId")), parentTaskIssueId: optionalString(formData.get("parentTaskIssueId")), labelIds: formData.getAll("labelIds").map(String).filter(Boolean) }; }
function optionalString(value: FormDataEntryValue | null) { const text = String(value ?? "").trim(); return text ? text : null; }

export default function TeamTasks({ loaderData, actionData }: Route.ComponentProps) {
  const { items, allItems, milestones, labels, members, projects, filters, section, selectedTaskId: initialTaskId, canWrite, canModerateComments, currentUserId, error } = loaderData;
  const navigation = useNavigation(); const detailFetcher = useFetcher<typeof loader>();
  const [searchParams] = useSearchParams();
  const [selectedTaskId, setSelectedTaskId] = useState<string | null>(initialTaskId); const [taskForm, setTaskForm] = useState<"create" | "edit" | null>(null); const [subtaskParent, setSubtaskParent] = useState<string | null>(null); const [milestoneEdit, setMilestoneEdit] = useState<TaskMilestoneDto | null>(null); const [labelEdit, setLabelEdit] = useState<TaskLabelDto | null>(null);
  useEffect(() => { if (actionData && "ok" in actionData && actionData.ok && "intent" in actionData && ["createTask", "createSubtask", "updateTask"].includes(String(actionData.intent))) { setTaskForm(null); setSubtaskParent(null); } }, [actionData]);
  useEffect(() => { if (initialTaskId) setSelectedTaskId(initialTaskId); }, [initialTaskId]);
  useEffect(() => { if (selectedTaskId) detailFetcher.load(`?taskId=${selectedTaskId}`); }, [selectedTaskId]);
  const detail = detailFetcher.data?.taskDetail?.id === selectedTaskId ? detailFetcher.data.taskDetail : null;
  const selected = selectedTaskId ? allItems.find((item) => item.id === selectedTaskId) ?? items.find((item) => item.id === selectedTaskId) ?? null : null;
  const q = String(filters.q ?? "").trim().toLowerCase();
  const visibleItems = useMemo(() => items.filter((item) => !item.parentTaskIssueId).filter((item) => !q || [item.title, item.description ?? "", item.projectName ?? "", item.milestone?.title ?? "", ...item.labels.map((label) => label.name), ...item.assignees.map((assignee) => assignee.displayName), ...item.reviewers.map((reviewer) => reviewer.displayName)].join(" ").toLowerCase().includes(q)), [items, q]);
  const open = allItems.filter((item) => isTaskOpen(item.status)); const done = allItems.filter((item) => item.status === TaskIssueStatus.Done || item.status === TaskIssueStatus.Closed); const overdue = open.filter((item) => item.dueDate && new Date(item.dueDate) < today());
  return <section className="space-y-6">
    <header className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div><h1 className="text-headline-lg font-bold text-on-surface">Studio work board</h1><p className="mt-1 text-body-sm text-on-surface-variant">Tasks, reviews, milestones, labels, comments, and child tasks.</p></div>{canWrite && <div className="flex flex-wrap gap-2"><button type="button" onClick={() => setTaskForm("create")} className={primaryButtonClass()}><span className="material-symbols-outlined text-[18px]">add</span>New task</button></div>}</header>
    {error && <ErrorBanner message={error} />}{actionData && "error" in actionData && actionData.error && <ErrorBanner message={actionData.error} />}
    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard icon="task_alt" label="Open" value={open.length} tone="primary" /><MetricCard icon="schedule" label="Overdue" value={overdue.length} tone="tertiary" /><MetricCard icon="flag" label="Milestones" value={milestones.length} /><MetricCard icon="check_circle" label="Completed" value={done.length} tone="secondary" /></div>
    <SectionTabs active={section} searchParams={searchParams} />
    {section === "board" && <><FilterBar filters={filters} members={members} milestones={milestones} labels={labels} /><BoardSection items={visibleItems} canWrite={canWrite} onOpen={setSelectedTaskId} /></>}
    {section === "milestones" && <MilestonesSection milestones={milestones} items={allItems} canWrite={canWrite} onMilestoneEdit={setMilestoneEdit} onTaskOpen={setSelectedTaskId} />}
    {section === "labels" && <LabelsSection labels={labels} items={allItems} canWrite={canWrite} onLabelEdit={setLabelEdit} onTaskOpen={setSelectedTaskId} />}
    <TaskDrawer open={Boolean(selectedTaskId)} task={detail} fallback={selected} loading={detailFetcher.state !== "idle"} members={members} canWrite={canWrite} canModerateComments={canModerateComments} currentUserId={currentUserId} onClose={() => setSelectedTaskId(null)} onEdit={() => setTaskForm("edit")} onSubtask={(id) => setSubtaskParent(id)} onRefresh={(id) => detailFetcher.load(`?taskId=${id}`)} />
    <TaskForm open={Boolean(taskForm) || Boolean(subtaskParent)} mode={taskForm} task={taskForm === "edit" ? detail : null} parentTaskId={subtaskParent} milestones={milestones} labels={labels} members={members} projects={projects} allTasks={allItems} onClose={() => { setTaskForm(null); setSubtaskParent(null); }} busy={navigation.state === "submitting"} />
    <MilestoneForm milestone={milestoneEdit} open={milestoneEdit !== null} onClose={() => setMilestoneEdit(null)} />
    <LabelForm label={labelEdit} open={labelEdit !== null} onClose={() => setLabelEdit(null)} />
  </section>;
}
function FilterBar({ filters, members, milestones, labels }: { filters: TaskIssueFilters & { q: string }; members: StudioMemberDto[]; milestones: TaskMilestoneDto[]; labels: TaskLabelDto[] }) { return <Form method="get" className="grid gap-3 rounded-lg border border-outline-variant bg-surface-container-low p-4 lg:grid-cols-[1.4fr_repeat(4,1fr)_auto]"><Input name="q" label="Search" defaultValue={filters.q} /><Select name="kind" label="Type" value={String(filters.kind ?? "")}><option value="">All</option><option value={TaskIssueKind.Task}>Tasks</option><option value={TaskIssueKind.Review}>Reviews</option></Select><Select name="status" label="Status" value={String(filters.status ?? "")}><option value="">All</option>{statuses.map((status) => <option key={status} value={status}>{taskStatusLabel(status)}</option>)}</Select><Select name="assigneeId" label="Assignee" value={String(filters.assigneeId ?? "")}><option value="">Anyone</option>{members.map((m) => <option key={m.userId} value={m.userId}>{m.displayName}</option>)}</Select><Select name="milestoneId" label="Milestone" value={String(filters.milestoneId ?? "")}><option value="">Any</option>{milestones.map((m) => <option key={m.id} value={m.id}>{m.title}</option>)}</Select><Select name="labelId" label="Label" value={String(filters.labelId ?? "")}><option value="">Any</option>{labels.map((l) => <option key={l.id} value={l.id}>{l.name}</option>)}</Select><div className="flex items-end"><button type="submit" className={primaryButtonClass("w-full justify-center")}>Apply</button></div></Form>; }

function SectionTabs({ active, searchParams }: { active: "board" | "milestones" | "labels"; searchParams: URLSearchParams }) { const tabs: { id: "board" | "milestones" | "labels"; label: string; icon: string }[] = [{ id: "board", label: "Board", icon: "view_kanban" }, { id: "milestones", label: "Milestones", icon: "flag" }, { id: "labels", label: "Labels", icon: "label" }]; return <nav className="flex flex-wrap gap-2 border-b border-outline-variant pb-2">{tabs.map((tab) => <Link key={tab.id} to={sectionHref(searchParams, tab.id)} className={`inline-flex items-center gap-2 rounded-lg px-3 py-2 text-label-lg font-medium transition-colors ${active === tab.id ? "bg-primary-container text-on-primary-container" : "text-on-surface-variant hover:bg-surface-container-high hover:text-on-surface"}`}><span className="material-symbols-outlined text-[18px]">{tab.icon}</span>{tab.label}</Link>)}</nav>; }
function sectionHref(searchParams: URLSearchParams, section: string) { const next = new URLSearchParams(searchParams); if (section === "board") next.delete("section"); else next.set("section", section); next.delete("taskId"); const query = next.toString(); return query ? `?${query}` : "."; }
function BoardSection({ items, canWrite, onOpen }: { items: TaskIssueDto[]; canWrite: boolean; onOpen: (id: string) => void }) { return <section>{items.length === 0 ? <EmptyState icon="view_kanban" title="No tasks match this view" hint={canWrite ? "Create a task or adjust the filters." : "Tasks will appear here."} /> : <div className="grid gap-4 lg:grid-cols-2 xl:grid-cols-4">{lanes.map((lane) => { const laneItems = items.filter((item) => lane.statuses.includes(item.status)); return <section key={lane.title} className="min-h-80 rounded-lg border border-outline-variant bg-surface-container-low"><header className="flex items-center justify-between border-b border-outline-variant px-3 py-2"><span className="flex items-center gap-2 text-label-lg font-semibold text-on-surface"><span className="h-2.5 w-2.5 rounded-full" style={{ backgroundColor: lane.color }} />{lane.title}</span><span className="text-label-md text-on-surface-variant">{laneItems.length}</span></header><div className="space-y-3 p-3">{laneItems.map((item) => <TaskCard key={item.id} item={item} canWrite={canWrite} onOpen={() => onOpen(item.id)} />)}{laneItems.length === 0 && <p className="px-1 py-8 text-center text-label-md text-on-surface-variant">Empty</p>}</div></section>; })}</div>}</section>; }
function MilestonesSection({ milestones, items, canWrite, onMilestoneEdit, onTaskOpen }: { milestones: TaskMilestoneDto[]; items: TaskIssueDto[]; canWrite: boolean; onMilestoneEdit: (m: TaskMilestoneDto) => void; onTaskOpen: (id: string) => void }) { const [selectedId, setSelectedId] = useState(milestones[0]?.id ?? "__none"); const groups = milestones.map((milestone) => ({ id: milestone.id, title: milestone.title, description: milestone.description || "No description.", dueDate: milestone.dueDate, status: milestone.status === TaskMilestoneStatus.Closed ? "Closed" : "Open", color: "#5B6CFF", icon: "flag", items: items.filter((item) => item.milestone?.id === milestone.id), milestone })); const unplanned = { id: "__none", title: "No milestone", description: "Tasks that have not been planned into a milestone.", dueDate: null, status: "Unplanned", color: "#8B95A1", icon: "outlined_flag", items: items.filter((item) => !item.milestone), milestone: null as TaskMilestoneDto | null }; const selected = groups.find((group) => group.id === selectedId) ?? unplanned; return <section className="space-y-4">{canWrite && <Panel title="New milestone"><MilestoneInline /></Panel>}<Panel title="Milestone breakdown"><div className="mb-4 max-w-md"><label className="text-label-md text-on-surface-variant">Milestone<select value={selected.id} onChange={(e) => setSelectedId(e.target.value)} className="mt-1 w-full rounded-lg border border-outline-variant bg-surface-container-high px-3 py-2 text-body-sm text-on-surface focus:border-primary focus:outline-none">{groups.map((group) => <option key={group.id} value={group.id}>{group.title}</option>)}<option value={unplanned.id}>{unplanned.title}</option></select></label></div><BreakdownCard icon={selected.icon} title={selected.title} description={selected.description} meta={`${selected.status} / ${formatDueDate(selected.dueDate)}`} color={selected.color} items={selected.items} canWrite={canWrite && Boolean(selected.milestone)} onEdit={selected.milestone ? () => onMilestoneEdit(selected.milestone!) : undefined} deleteIntent={selected.milestone ? "deleteMilestone" : undefined} id={selected.milestone?.id} deleteLabel={selected.title} onTaskOpen={onTaskOpen} /></Panel>{milestones.length === 0 && unplanned.items.length === 0 && <EmptyState icon="flag" title="No milestone breakdowns" hint={canWrite ? "Create a milestone or assign tasks to one." : "Milestones will appear here."} />}</section>; }
function LabelsSection({ labels, items, canWrite, onLabelEdit, onTaskOpen }: { labels: TaskLabelDto[]; items: TaskIssueDto[]; canWrite: boolean; onLabelEdit: (l: TaskLabelDto) => void; onTaskOpen: (id: string) => void }) { const [selectedId, setSelectedId] = useState(labels[0]?.id ?? "__untagged"); const groups = labels.map((label) => ({ id: label.id, title: label.name, description: `Tasks tagged with ${label.name}.`, color: label.color, icon: "label", items: items.filter((item) => item.labels.some((x) => x.id === label.id)), label })); const untagged = { id: "__untagged", title: "Untagged tasks", description: "Tasks without labels.", color: "#8B95A1", icon: "label_off", items: items.filter((item) => item.labels.length === 0), label: null as TaskLabelDto | null }; const selected = groups.find((group) => group.id === selectedId) ?? untagged; return <section className="space-y-4">{canWrite && <Panel title="New label"><LabelInline /></Panel>}<Panel title="Label breakdown"><div className="mb-4 max-w-md"><label className="text-label-md text-on-surface-variant">Label<select value={selected.id} onChange={(e) => setSelectedId(e.target.value)} className="mt-1 w-full rounded-lg border border-outline-variant bg-surface-container-high px-3 py-2 text-body-sm text-on-surface focus:border-primary focus:outline-none">{groups.map((group) => <option key={group.id} value={group.id}>{group.title}</option>)}<option value={untagged.id}>{untagged.title}</option></select></label></div><BreakdownCard icon={selected.icon} title={selected.title} description={selected.description} meta={selected.label ? "Label" : "No label"} color={selected.color} items={selected.items} canWrite={canWrite && Boolean(selected.label)} onEdit={selected.label ? () => onLabelEdit(selected.label!) : undefined} deleteIntent={selected.label ? "deleteLabel" : undefined} id={selected.label?.id} deleteLabel={selected.title} onTaskOpen={onTaskOpen} /></Panel>{labels.length === 0 && untagged.items.length === 0 && <EmptyState icon="label" title="No label breakdowns" hint={canWrite ? "Create a label or tag tasks." : "Labels will appear here."} />}</section>; }
function BreakdownCard({ id, icon, title, description, meta, color, items, canWrite, onEdit, deleteIntent, deleteLabel, onTaskOpen }: { id?: string; icon: string; title: string; description: string; meta: string; color: string; items: TaskIssueDto[]; canWrite: boolean; onEdit?: () => void; deleteIntent?: string; deleteLabel?: string; onTaskOpen: (id: string) => void }) { const open = items.filter((item) => isTaskOpen(item.status)).length; const done = items.filter((item) => item.status === TaskIssueStatus.Done || item.status === TaskIssueStatus.Closed).length; const overdue = items.filter((item) => isTaskOpen(item.status) && item.dueDate && new Date(item.dueDate) < today()).length; const progress = items.length ? Math.round((done / items.length) * 100) : 0; return <article className="rounded-lg border border-outline-variant bg-surface-container-low p-4"><header className="flex items-start justify-between gap-3"><div className="min-w-0"><div className="flex items-center gap-2"><span className="flex h-8 w-8 items-center justify-center rounded-lg bg-surface-container-high text-on-surface-variant"><span className="material-symbols-outlined text-[18px]">{icon}</span></span><h2 className="truncate text-body-md font-bold text-on-surface">{title}</h2></div><p className="mt-2 text-body-sm text-on-surface-variant">{description}</p><p className="mt-1 text-label-md text-on-surface-variant">{meta}</p></div><span className="mt-1 h-3 w-3 shrink-0 rounded-full" style={{ backgroundColor: color }} /></header><div className="mt-4 grid grid-cols-4 gap-2 text-center"><BreakdownMetric label="Tasks" value={items.length} /><BreakdownMetric label="Open" value={open} /><BreakdownMetric label="Done" value={done} /><BreakdownMetric label="Late" value={overdue} /></div><div className="mt-4"><div className="flex items-center justify-between text-label-md text-on-surface-variant"><span>Progress</span><span>{progress}%</span></div><div className="mt-1 h-2 overflow-hidden rounded-full bg-surface-container-high"><div className="h-full rounded-full bg-primary" style={{ width: `${progress}%` }} /></div></div><div className="mt-4 space-y-2">{items.slice(0, 8).map((item) => <TaskBreakdownRow key={item.id} item={item} onOpen={() => onTaskOpen(item.id)} />)}{items.length === 0 && <p className="rounded-lg border border-dashed border-outline-variant px-3 py-4 text-center text-label-md text-on-surface-variant">No tasks in this section.</p>}{items.length > 8 && <p className="text-label-md text-on-surface-variant">+{items.length - 8} more tasks</p>}</div>{canWrite && id && onEdit && deleteIntent && <div className="mt-4 flex justify-end gap-2"><button type="button" onClick={onEdit} className={secondaryButtonClass()}><span className="material-symbols-outlined text-[18px]">edit</span>Edit</button><DeleteConfirmButton id={id} intent={deleteIntent} label={deleteLabel ?? title} /></div>}</article>; }
function DeleteConfirmButton({ id, intent, label }: { id: string; intent: string; label: string }) { const [open, setOpen] = useState(false); return <><button type="button" onClick={() => setOpen(true)} className={dangerButtonClass()}><span className="material-symbols-outlined text-[18px]">delete</span>Delete</button>{open && <Modal title={`Delete ${label}?`} onClose={() => setOpen(false)}><p className="text-body-sm text-on-surface-variant">This cannot be undone. Existing tasks will keep their history, but this item will be removed.</p><Form method="post" className="mt-4 flex justify-end gap-2"><input type="hidden" name="intent" value={intent} /><input type="hidden" name="id" value={id} /><button type="button" onClick={() => setOpen(false)} className={secondaryButtonClass()}>Cancel</button><button type="submit" className={dangerButtonClass()}><span className="material-symbols-outlined text-[18px]">delete</span>Delete</button></Form></Modal>}</>; }
function BreakdownMetric({ label, value }: { label: string; value: number }) { return <div className="rounded-lg bg-surface-container-high px-2 py-2"><p className="text-body-sm font-bold text-on-surface">{value}</p><p className="text-label-sm text-on-surface-variant">{label}</p></div>; }
function TaskBreakdownRow({ item, onOpen }: { item: TaskIssueDto; onOpen: () => void }) { return <button type="button" onClick={onOpen} className="flex w-full items-center justify-between gap-3 rounded-lg border border-outline-variant bg-surface-container px-3 py-2 text-left hover:border-primary/40"><span className="min-w-0"><span className="block truncate text-body-sm font-medium text-on-surface">{item.title}</span><span className="block truncate text-label-md text-on-surface-variant">{taskStatusLabel(item.status)} / {formatDueDate(item.dueDate)}</span></span><span className="material-symbols-outlined text-[18px] text-on-surface-variant">chevron_right</span></button>; }

function TaskCard({ item, canWrite, onOpen }: { item: TaskIssueDto; canWrite: boolean; onOpen: () => void }) { const fetcher = useFetcher(); const people = item.kind === TaskIssueKind.Review ? item.reviewers : item.assignees; const emptyPeople = item.kind === TaskIssueKind.Review ? "No reviewers" : "Unassigned"; return <article className="rounded-lg border border-outline-variant bg-surface-container p-3 shadow-sm"><button type="button" onClick={onOpen} className="block w-full text-left"><div className="flex items-start justify-between gap-2"><span className="inline-flex items-center gap-1 rounded-full bg-surface-container-high px-2 py-0.5 text-label-sm text-on-surface-variant"><span className="material-symbols-outlined text-[15px]">{item.kind === TaskIssueKind.Review ? "rate_review" : "task_alt"}</span>{taskKindLabel(item.kind)}</span><StatusBadge label={taskStatusLabel(item.status)} tone={statusTone(item.status)} dotPosition="end" /></div><h3 className="mt-3 text-body-md font-semibold leading-snug text-on-surface">{item.title}</h3><p className="mt-2 line-clamp-2 text-label-md text-on-surface-variant">{item.description || "No description"}</p><div className="mt-3 space-y-1 text-label-md text-on-surface-variant"><Meta icon="folder" text={item.projectName ?? "No project"} /><Meta icon="flag" text={item.milestone?.title ?? "No milestone"} /><Meta icon="event" text={formatDueDate(item.dueDate)} /></div><Labels labels={item.labels} /><div className="mt-3 flex items-center justify-between gap-2 text-label-sm text-on-surface-variant"><span className="inline-flex min-w-0 items-center gap-1"><span className="material-symbols-outlined text-[16px]">{item.kind === TaskIssueKind.Review ? "rate_review" : "person"}</span><span className="truncate">{people.length ? people.map(initials).join(" ") : emptyPeople}</span></span><span className="flex items-center gap-3"><span className="inline-flex items-center gap-1"><span className="material-symbols-outlined text-[16px]">forum</span>{item.commentsCount}</span><span className="inline-flex items-center gap-1"><span className="material-symbols-outlined text-[16px]">account_tree</span>{item.completedSubtaskCount}/{item.subtaskCount}</span></span></div></button>{canWrite && <fetcher.Form method="post" className="mt-3"><input type="hidden" name="intent" value="status" /><input type="hidden" name="id" value={item.id} /><select name="status" defaultValue={item.status} onChange={(e) => e.currentTarget.form?.requestSubmit()} className="w-full rounded-md border border-outline-variant bg-surface-container-high px-2 py-1.5 text-label-md text-on-surface focus:border-primary focus:outline-none">{statuses.map((status) => <option key={status} value={status}>{taskStatusLabel(status)}</option>)}</select></fetcher.Form>}</article>; }

function TaskDrawer({ open, task, fallback, loading, members, canWrite, canModerateComments, currentUserId, onClose, onEdit, onSubtask, onRefresh }: { open: boolean; task: TaskIssueDetailDto | null; fallback: TaskIssueDto | null; loading: boolean; members: StudioMemberDto[]; canWrite: boolean; canModerateComments: boolean; currentUserId: string; onClose: () => void; onEdit: () => void; onSubtask: (id: string) => void; onRefresh: (id: string) => void }) { const mutation = useFetcher<{ ok?: boolean; error?: string; intent?: string; taskId?: string }>(); const shown = task ?? fallback; useEffect(() => { if (mutation.state === "idle" && mutation.data?.ok && mutation.data.taskId) { if (mutation.data.intent === "deleteTask" && mutation.data.taskId === shown?.id) onClose(); else onRefresh(mutation.data.taskId); } }, [mutation.state, mutation.data?.ok, mutation.data?.intent, mutation.data?.taskId]); if (!open || !shown) return null; const people = shown.kind === TaskIssueKind.Review ? shown.reviewers : shown.assignees; const peopleLabel = shown.kind === TaskIssueKind.Review ? "Reviewers" : "Assignees"; const emptyPeople = shown.kind === TaskIssueKind.Review ? "No reviewers." : "Unassigned."; return <div className="fixed inset-0 z-50 flex justify-end"><button type="button" aria-label="Close details" onClick={onClose} className="absolute inset-0 bg-black/40" /><aside className="relative z-10 flex h-full w-full max-w-2xl flex-col border-l border-outline-variant bg-surface shadow-xl"><header className="border-b border-outline-variant p-5"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><div className="mb-2 flex flex-wrap items-center gap-2"><StatusBadge label={taskStatusLabel(shown.status)} tone={statusTone(shown.status)} dotPosition="end" /><span className="text-label-md text-on-surface-variant">{taskKindLabel(shown.kind)}</span></div><h2 className="text-headline-sm font-bold text-on-surface">{shown.title}</h2><p className="mt-1 text-label-md text-on-surface-variant">{shown.projectName ?? "No project"} / {shown.milestone?.title ?? "No milestone"} / {formatDueDate(shown.dueDate)}</p></div><button type="button" onClick={onClose} className={iconButtonClass()}><span className="material-symbols-outlined text-[18px]">close</span></button></div>{canWrite && <div className="mt-4 flex flex-wrap gap-2"><button type="button" onClick={onEdit} className={secondaryButtonClass()}><span className="material-symbols-outlined text-[18px]">edit</span>Edit</button><button type="button" onClick={() => onSubtask(shown.id)} className={secondaryButtonClass()}><span className="material-symbols-outlined text-[18px]">account_tree</span>Child task</button><mutation.Form method="post" onSubmit={(e) => !confirm("Delete this task and its child tasks permanently?") && e.preventDefault()}><input type="hidden" name="intent" value="deleteTask" /><input type="hidden" name="id" value={shown.id} /><button type="submit" className={dangerButtonClass()}><span className="material-symbols-outlined text-[18px]">delete</span>Delete</button></mutation.Form></div>}{mutation.data?.error && <div className="mt-3"><ErrorBanner message={mutation.data.error} /></div>}</header><div className="flex-1 space-y-6 overflow-y-auto p-5">{loading && !task && <p className="text-body-sm text-on-surface-variant">Loading...</p>}<section><h3 className="text-label-lg font-semibold text-on-surface">Description</h3><p className="mt-2 whitespace-pre-wrap text-body-sm text-on-surface-variant">{shown.description || "No description."}</p></section><section><h3 className="text-label-lg font-semibold text-on-surface">{peopleLabel}</h3><p className="mt-2 text-body-sm text-on-surface-variant">{people.length ? people.map((person) => person.displayName).join(", ") : emptyPeople}</p><Labels labels={shown.labels} /></section><section><div className="flex items-center justify-between"><h3 className="text-label-lg font-semibold text-on-surface">Child tasks</h3><span className="text-label-md text-on-surface-variant">{shown.completedSubtaskCount}/{shown.subtaskCount}</span></div><div className="mt-3 space-y-2">{task?.subtasks.map((subtask) => <div key={subtask.id} className="flex items-center justify-between gap-3 rounded-lg border border-outline-variant bg-surface-container-low p-3"><div className="min-w-0"><p className="truncate text-body-sm font-medium text-on-surface">{subtask.title}</p><p className="text-label-md text-on-surface-variant">{taskStatusLabel(subtask.status)}</p></div>{canWrite && <mutation.Form method="post" onSubmit={(e) => !confirm("Delete this child task permanently?") && e.preventDefault()}><input type="hidden" name="intent" value="deleteTask" /><input type="hidden" name="id" value={subtask.id} /><input type="hidden" name="taskId" value={shown.id} /><button type="submit" className={iconButtonClass("text-error")}><span className="material-symbols-outlined text-[18px]">delete</span></button></mutation.Form>}</div>)}{task && task.subtasks.length === 0 && <p className="text-body-sm text-on-surface-variant">No child tasks.</p>}</div></section><section><h3 className="text-label-lg font-semibold text-on-surface">Comments</h3><mutation.Form method="post" className="mt-3 space-y-2"><input type="hidden" name="intent" value="createComment" /><input type="hidden" name="taskId" value={shown.id} /><MentionTextarea name="body" rows={3} required placeholder="Add a comment" members={members} /><button type="submit" className={primaryButtonClass()}>Comment</button></mutation.Form><div className="mt-4 space-y-3">{task?.comments.map((comment) => <Comment key={comment.id} comment={comment} taskId={shown.id} members={members} mutation={mutation} canEdit={comment.authorUserId === currentUserId} canDelete={canModerateComments || comment.authorUserId === currentUserId} />)}{task && task.comments.length === 0 && <p className="text-body-sm text-on-surface-variant">No comments.</p>}</div></section><section><h3 className="text-label-lg font-semibold text-on-surface">Activity</h3><div className="mt-3 space-y-3">{task?.activity.map((a) => <div key={a.id} className="border-l-2 border-outline-variant pl-3"><p className="text-body-sm text-on-surface">{a.summary}</p><p className="text-label-md text-on-surface-variant">{a.actorDisplayName ?? "System"} / {formatDateTime(a.createdAt)}</p></div>)}{task && task.activity.length === 0 && <p className="text-body-sm text-on-surface-variant">No activity.</p>}</div></section></div></aside></div>; }

function Comment({ comment, taskId, members, mutation, canEdit, canDelete }: { comment: TaskCommentDto; taskId: string; members: StudioMemberDto[]; mutation: ReturnType<typeof useFetcher>; canEdit: boolean; canDelete: boolean }) { const [editing, setEditing] = useState(false); return <div className="rounded-lg border border-outline-variant bg-surface-container-low p-3"><div className="flex items-start justify-between gap-3"><div><p className="text-label-lg font-semibold text-on-surface">{comment.authorDisplayName}</p><p className="text-label-md text-on-surface-variant">{formatDateTime(comment.createdAt)}{comment.editedAt ? " / edited" : ""}</p></div><div className="flex gap-1">{canEdit && <button type="button" onClick={() => setEditing(!editing)} className={iconButtonClass()}><span className="material-symbols-outlined text-[18px]">edit</span></button>}{canDelete && <mutation.Form method="post" onSubmit={(e) => !confirm("Delete this comment permanently?") && e.preventDefault()}><input type="hidden" name="intent" value="deleteComment" /><input type="hidden" name="id" value={comment.id} /><input type="hidden" name="taskId" value={taskId} /><button type="submit" className={iconButtonClass("text-error")}><span className="material-symbols-outlined text-[18px]">delete</span></button></mutation.Form>}</div></div>{editing ? <mutation.Form method="post" className="mt-3 space-y-2" onSubmit={() => setEditing(false)}><input type="hidden" name="intent" value="updateComment" /><input type="hidden" name="id" value={comment.id} /><input type="hidden" name="taskId" value={taskId} /><MentionTextarea name="body" rows={3} defaultValue={comment.body} members={members} /><button type="submit" className={primaryButtonClass()}>Save</button></mutation.Form> : <p className="mt-2 whitespace-pre-wrap text-body-sm text-on-surface-variant"><MentionText body={comment.body} members={members} /></p>}</div>; }

function MentionTextarea({ name, rows, required = false, placeholder = "", defaultValue = "", members }: { name: string; rows: number; required?: boolean; placeholder?: string; defaultValue?: string; members: StudioMemberDto[] }) { const ref = useRef<HTMLTextAreaElement>(null); const [value, setValue] = useState(defaultValue); const [caret, setCaret] = useState(defaultValue.length); const active = activeMention(value, caret); const suggestions = active ? mentionSuggestions(members, active.query) : []; const choose = (member: StudioMemberDto) => { if (!active) return; const alias = preferredMentionAlias(member, members); const next = `${value.slice(0, active.start)}@${alias} ${value.slice(caret)}`; const nextCaret = active.start + alias.length + 2; setValue(next); setCaret(nextCaret); window.setTimeout(() => { ref.current?.focus(); ref.current?.setSelectionRange(nextCaret, nextCaret); }, 0); }; return <div className="relative"><textarea ref={ref} name={name} rows={rows} required={required} placeholder={placeholder} value={value} onChange={(e) => { setValue(e.target.value); setCaret(e.target.selectionStart); }} onClick={(e) => setCaret(e.currentTarget.selectionStart)} onKeyUp={(e) => setCaret(e.currentTarget.selectionStart)} className={textareaClass()} />{suggestions.length > 0 && <div className="absolute z-30 mt-1 max-h-64 w-full overflow-y-auto rounded-lg border border-outline-variant bg-surface-container p-1 shadow-xl">{suggestions.map((member) => <button key={member.userId} type="button" onClick={() => choose(member)} className="flex w-full items-center gap-3 rounded-md px-3 py-2 text-left text-on-surface hover:bg-surface-container-high"><span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-surface text-label-sm font-semibold">{initials(member)}</span><span className="min-w-0 flex-1"><span className="block truncate text-label-lg font-medium">{member.displayName}</span><span className="block truncate text-label-sm text-on-surface-variant">@{preferredMentionAlias(member, members)} / {member.email}</span></span></button>)}</div>}</div>; }
function MentionText({ body, members }: { body: string; members: StudioMemberDto[] }) { return <>{body.split(/(@[A-Za-z0-9._%+\-@]+)/g).map((part, index) => { const member = part.startsWith("@") ? resolveMention(part, members) : null; return member ? <span key={`${part}-${index}`} className="rounded bg-primary-container px-1 font-medium text-on-primary-container">{part}</span> : <span key={`${part}-${index}`}>{part}</span>; })}</>; }
function activeMention(value: string, caret: number) { const before = value.slice(0, caret); const tokenStart = Math.max(before.lastIndexOf(" "), before.lastIndexOf("\n"), before.lastIndexOf("\t")) + 1; const token = before.slice(tokenStart); return token.startsWith("@") ? { start: tokenStart, query: token.slice(1).toLowerCase() } : null; }
function mentionSuggestions(members: StudioMemberDto[], query: string) { const q = query.trim().toLowerCase(); return members.filter((member) => q.length === 0 || memberAliases(member).some((alias) => alias.startsWith(q) || alias.includes(q))).slice(0, 6); }
function resolveMention(token: string, members: StudioMemberDto[]) { const alias = token.slice(1).trim().replace(/[.,;:!?)}\]]+$/, "").toLowerCase(); const matches = members.filter((member) => memberAliases(member).includes(alias)); return matches.length === 1 ? matches[0] : null; }
function preferredMentionAlias(member: StudioMemberDto, members: StudioMemberDto[]) { const candidates = [mentionSlug(member.displayName), member.email.split("@")[0].toLowerCase(), member.email.toLowerCase()].filter(Boolean); return candidates.find((candidate) => members.filter((m) => memberAliases(m).includes(candidate)).length === 1) ?? member.email.toLowerCase(); }
function memberAliases(member: StudioMemberDto) { return Array.from(new Set([member.email.toLowerCase(), member.email.split("@")[0].toLowerCase(), mentionSlug(member.displayName)].filter(Boolean))); }
function mentionSlug(value: string) { return value.trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, ""); }

function TaskForm({ open, mode, task, parentTaskId, milestones, labels, members, projects, allTasks, onClose, busy }: { open: boolean; mode: "create" | "edit" | null; task: TaskIssueDetailDto | null; parentTaskId: string | null; milestones: TaskMilestoneDto[]; labels: TaskLabelDto[]; members: StudioMemberDto[]; projects: ProjectDto[]; allTasks: TaskIssueDto[]; onClose: () => void; busy: boolean }) { if (!open) return null; const isEdit = Boolean(task); const kind = parentTaskId ? TaskIssueKind.Task : task?.kind ?? TaskIssueKind.Task; const isReview = kind === TaskIssueKind.Review; const selectedAssignees = new Set(task?.assignees.map((p) => p.userId) ?? []); const selectedReviewers = new Set(task?.reviewers.map((p) => p.userId) ?? []); const selectedLabels = new Set(task?.labels.map((l) => l.id) ?? []); const intent = isEdit ? "updateTask" : parentTaskId ? "createSubtask" : "createTask"; const title = isEdit ? `Edit ${isReview ? "review" : "task"}` : parentTaskId ? "New child task" : "New task"; return <Modal title={title} onClose={onClose}><Form method="post" className="space-y-3"><input type="hidden" name="intent" value={intent} /><input type="hidden" name="kind" value={kind} />{task && <input type="hidden" name="id" value={task.id} />}<input type="hidden" name="parentTaskIssueId" value={parentTaskId ?? task?.parentTaskIssueId ?? ""} /><div className="grid gap-3 md:grid-cols-2"><Input name="title" label={isReview ? "Review title" : "Title"} defaultValue={task?.title ?? ""} required /><Select name="projectId" label="Project" value={task?.projectId ?? ""}><option value="">No project</option>{projects.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}</Select><Select name="milestoneId" label="Milestone" value={task?.milestone?.id ?? ""}><option value="">No milestone</option>{milestones.map((m) => <option key={m.id} value={m.id}>{m.title}</option>)}</Select><DatePickerField name="dueDate" label="Due date" defaultValue={dateInput(task?.dueDate ?? null)} />{isEdit && !parentTaskId && <Select name="parentTaskIssueId" label="Parent" value={task?.parentTaskIssueId ?? ""}><option value="">No parent</option>{allTasks.filter((i) => i.id !== task?.id).map((i) => <option key={i.id} value={i.id}>{i.title}</option>)}</Select>}</div>{isReview ? <MemberChipMultiSelect name="reviewerIds" label="Reviewers" members={members} selected={selectedReviewers} emptyIcon="group_off" emptyText="No teammates available." /> : <div className="grid gap-3 md:grid-cols-2"><MemberChipMultiSelect name="assigneeIds" label="Assignees" members={members} selected={selectedAssignees} emptyIcon="group_off" emptyText="No teammates available." /><MemberChipMultiSelect name="reviewerIds" label="Reviewers" members={members} selected={selectedReviewers} emptyIcon="group_off" emptyText="No teammates available." /></div>}<LabelChipMultiSelect labels={labels} selected={selectedLabels} /><label className="block text-label-md text-on-surface-variant">Description<textarea name="description" rows={4} defaultValue={task?.description ?? ""} className={textareaClass("mt-1")} /></label><div className="flex justify-end gap-2 pt-2"><button type="button" onClick={onClose} className={secondaryButtonClass()}>Cancel</button><button type="submit" disabled={busy} className={primaryButtonClass()}>{isEdit ? "Save" : "Create"}</button></div></Form></Modal>; }
function MemberChipMultiSelect({ name, label, members, selected, emptyIcon, emptyText }: { name: string; label: string; members: StudioMemberDto[]; selected: Set<string>; emptyIcon: string; emptyText: string }) { const [value, setValue] = useState(() => new Set(selected)); const [open, setOpen] = useState(false); const selectedMembers = members.filter((member) => value.has(member.userId)); const toggle = (id: string) => setValue((current) => { const next = new Set(current); if (next.has(id)) next.delete(id); else next.add(id); return next; }); const summary = selectedMembers.length === 0 ? "None selected" : selectedMembers.length === 1 ? selectedMembers[0].displayName : `${selectedMembers.length} selected`; return <div className="relative"><span className="block text-label-md text-on-surface-variant">{label}</span>{[...value].map((id) => <input key={id} type="hidden" name={name} value={id} />)}{members.length === 0 ? <div className="mt-1"><EmptyVisual icon={emptyIcon} text={emptyText} /></div> : <><button type="button" onClick={() => setOpen(!open)} className="mt-1 flex min-h-11 w-full items-center justify-between gap-2 rounded-lg border border-outline-variant bg-surface-container-high px-3 py-2 text-left text-body-sm text-on-surface hover:bg-surface-container focus:border-primary focus:outline-none"><span className="flex min-w-0 items-center gap-2">{selectedMembers.slice(0, 3).map((member) => <span key={member.userId} className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-surface text-label-sm font-semibold text-on-surface">{initials(member)}</span>)}<span className="truncate">{summary}</span></span><span className="material-symbols-outlined text-[18px]">{open ? "expand_less" : "expand_more"}</span></button>{open && <div className="absolute z-30 mt-2 max-h-72 w-full overflow-y-auto rounded-lg border border-outline-variant bg-surface-container p-1 shadow-xl"><div className="border-b border-outline-variant px-3 py-2 text-label-md font-semibold text-on-surface">{label}</div>{members.map((member) => { const active = value.has(member.userId); return <button key={member.userId} type="button" onClick={() => toggle(member.userId)} className="flex w-full items-center gap-3 rounded-md px-3 py-2 text-left text-on-surface hover:bg-surface-container-high"><span className={`material-symbols-outlined w-5 text-[18px] ${active ? "text-primary" : "text-transparent"}`}>check</span><span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-surface text-label-sm font-semibold text-on-surface">{initials(member)}</span><span className="min-w-0 flex-1"><span className="block truncate text-label-lg font-medium">{member.displayName}</span><span className="block truncate text-label-sm text-on-surface-variant">{member.email}</span></span></button>; })}</div>}</>}</div>; }
function LabelChipMultiSelect({ labels, selected }: { labels: TaskLabelDto[]; selected: Set<string> }) { const [value, setValue] = useState(() => new Set(selected)); const toggle = (id: string) => setValue((current) => { const next = new Set(current); if (next.has(id)) next.delete(id); else next.add(id); return next; }); return <fieldset className="space-y-2"><legend className="text-label-md text-on-surface-variant">Labels</legend>{[...value].map((id) => <input key={id} type="hidden" name="labelIds" value={id} />)}{labels.length === 0 ? <EmptyVisual icon="label_off" text="Create labels to tag tasks." /> : <div className="flex flex-wrap gap-2">{labels.map((label) => { const active = value.has(label.id); return <button key={label.id} type="button" onClick={() => toggle(label.id)} className={`inline-flex min-h-10 items-center gap-2 rounded-lg border px-3 py-2 text-label-md font-medium transition-colors ${active ? "border-primary bg-primary-container text-on-primary-container" : "border-outline-variant bg-surface-container-high text-on-surface hover:bg-surface-container"}`}><span className="h-3 w-3 rounded-full" style={{ backgroundColor: label.color }} /><span>{label.name}</span><span className="material-symbols-outlined text-[17px]">{active ? "check" : "add"}</span></button>; })}</div>}</fieldset>; }
function DatePickerField({ name, label, defaultValue = "" }: { name: string; label: string; defaultValue?: string }) { const [value, setValue] = useState(defaultValue); const [open, setOpen] = useState(false); const [month, setMonth] = useState(() => value ? new Date(`${value}T00:00:00`) : new Date()); const days = calendarDays(month); return <div className="relative"><input type="hidden" name={name} value={value} /><span className="block text-label-md text-on-surface-variant">{label}</span><button type="button" onClick={() => setOpen(!open)} className="mt-1 flex w-full items-center justify-between rounded-lg border border-outline-variant bg-surface-container-high px-3 py-2 text-left text-body-sm text-on-surface focus:border-primary focus:outline-none"><span>{value ? formatDueDate(value) : "No due date"}</span><span className="material-symbols-outlined text-[18px]">calendar_month</span></button>{open && <div className="absolute z-20 mt-2 w-72 rounded-lg border border-outline-variant bg-surface-container p-3 shadow-xl"><div className="mb-2 flex items-center justify-between"><button type="button" onClick={() => setMonth(addMonths(month, -1))} className={iconButtonClass()}><span className="material-symbols-outlined text-[18px]">chevron_left</span></button><span className="text-label-lg font-semibold text-on-surface">{new Intl.DateTimeFormat("en", { month: "long", year: "numeric" }).format(month)}</span><button type="button" onClick={() => setMonth(addMonths(month, 1))} className={iconButtonClass()}><span className="material-symbols-outlined text-[18px]">chevron_right</span></button></div><div className="grid grid-cols-7 gap-1 text-center text-label-sm text-on-surface-variant">{["S", "M", "T", "W", "T", "F", "S"].map((day, index) => <span key={`${day}-${index}`} className="py-1">{day}</span>)}</div><div className="mt-1 grid grid-cols-7 gap-1">{days.map((day) => { const date = toDateInput(day); const active = value === date; const muted = day.getMonth() !== month.getMonth(); return <button key={date} type="button" onClick={() => { setValue(date); setOpen(false); }} className={`h-8 rounded-md text-label-md transition-colors ${active ? "bg-primary text-on-primary" : muted ? "text-on-surface-variant hover:bg-surface-container-high" : "text-on-surface hover:bg-surface-container-high"}`}>{day.getDate()}</button>; })}</div><button type="button" onClick={() => { setValue(""); setOpen(false); }} className={secondaryButtonClass("mt-3 w-full justify-center")}>Clear</button></div>}</div>; }
function ColorPickerField({ name, label, defaultValue = "#5B6CFF" }: { name: string; label: string; defaultValue?: string }) { const swatches = ["#5B6CFF", "#0EA5A4", "#16A34A", "#D97706", "#DC2626", "#9333EA", "#2563EB", "#64748B"]; const [value, setValue] = useState(normalizeHex(defaultValue)); const [text, setText] = useState(value); const choose = (color: string) => { setValue(color); setText(color); }; return <div><input type="hidden" name={name} value={value} /><span className="block text-label-md text-on-surface-variant">{label}</span><div className="mt-1 flex flex-wrap items-center gap-2 rounded-lg border border-outline-variant bg-surface-container-high p-2">{swatches.map((color) => <button key={color} type="button" onClick={() => choose(color)} aria-label={color} className={`h-8 w-8 rounded-md border ${value.toLowerCase() === color.toLowerCase() ? "border-on-surface ring-2 ring-primary" : "border-outline-variant"}`} style={{ backgroundColor: color }} />)}<input value={text} onChange={(e) => { setText(e.target.value); const normalized = normalizeHex(e.target.value, ""); if (normalized) setValue(normalized); }} onBlur={() => setText(value)} className="min-w-24 flex-1 rounded-md border border-outline-variant bg-surface px-2 py-1.5 text-label-md text-on-surface focus:border-primary focus:outline-none" /></div></div>; }
function EmptyVisual({ icon, text }: { icon: string; text: string }) { return <div className="flex items-center gap-2 rounded-lg border border-dashed border-outline-variant bg-surface-container-high px-3 py-3 text-label-md text-on-surface-variant"><span className="material-symbols-outlined text-[18px]">{icon}</span><span>{text}</span></div>; }
function MilestoneInline() { return <Form method="post" className="space-y-3"><input type="hidden" name="intent" value="createMilestone" /><Input name="title" label="Title" required /><DatePickerField name="dueDate" label="Due date" /><label className="block text-label-md text-on-surface-variant">Description<textarea name="description" rows={3} className={textareaClass("mt-1")} /></label><button type="submit" className={primaryButtonClass("w-full justify-center")}>Create</button></Form>; }
function LabelInline() { return <Form method="post" className="space-y-3"><input type="hidden" name="intent" value="createLabel" /><Input name="name" label="Name" required /><ColorPickerField name="color" label="Color" /><button type="submit" className={primaryButtonClass("w-full justify-center")}>Create</button></Form>; }
function MilestoneForm({ milestone, open, onClose }: { milestone: TaskMilestoneDto | null; open: boolean; onClose: () => void }) { if (!open || !milestone) return null; return <Modal title="Edit milestone" onClose={onClose}><Form method="post" className="space-y-3" onSubmit={onClose}><input type="hidden" name="intent" value="updateMilestone" /><input type="hidden" name="id" value={milestone.id} /><Input name="title" label="Title" defaultValue={milestone.title} required /><DatePickerField name="dueDate" label="Due date" defaultValue={dateInput(milestone.dueDate)} /><Select name="status" label="Status" value={String(milestone.status)}><option value={TaskMilestoneStatus.Open}>Open</option><option value={TaskMilestoneStatus.Closed}>Closed</option></Select><label className="block text-label-md text-on-surface-variant">Description<textarea name="description" rows={3} defaultValue={milestone.description ?? ""} className={textareaClass("mt-1")} /></label><div className="flex justify-end gap-2"><button type="button" onClick={onClose} className={secondaryButtonClass()}>Cancel</button><button type="submit" className={primaryButtonClass()}>Save</button></div></Form></Modal>; }
function LabelForm({ label, open, onClose }: { label: TaskLabelDto | null; open: boolean; onClose: () => void }) { if (!open || !label) return null; return <Modal title="Edit label" onClose={onClose}><Form method="post" className="space-y-3" onSubmit={onClose}><input type="hidden" name="intent" value="updateLabel" /><input type="hidden" name="id" value={label.id} /><Input name="name" label="Name" defaultValue={label.name} required /><ColorPickerField name="color" label="Color" defaultValue={label.color} /><div className="flex justify-end gap-2"><button type="button" onClick={onClose} className={secondaryButtonClass()}>Cancel</button><button type="submit" className={primaryButtonClass()}>Save</button></div></Form></Modal>; }
function Panel({ title, children }: { title: string; children: ReactNode }) { return <section className="rounded-lg border border-outline-variant bg-surface-container-low p-4"><h2 className="mb-3 text-body-sm font-bold text-on-surface">{title}</h2>{children}</section>; }
function Select({ name, label, value, children }: { name: string; label: string; value: string; children: ReactNode }) { return <label className="text-label-md text-on-surface-variant">{label}<select name={name} defaultValue={value} className="mt-1 w-full rounded-lg border border-outline-variant bg-surface-container-high px-3 py-2 text-body-sm text-on-surface focus:border-primary focus:outline-none">{children}</select></label>; }
function Input({ name, label, type = "text", defaultValue = "", required = false }: { name: string; label: string; type?: string; defaultValue?: string; required?: boolean }) { return <label className="text-label-md text-on-surface-variant">{label}<input name={name} type={type} defaultValue={defaultValue} required={required} className="mt-1 w-full rounded-lg border border-outline-variant bg-surface-container-high px-3 py-2 text-body-sm text-on-surface focus:border-primary focus:outline-none" /></label>; }
function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) { return <div className="fixed inset-0 z-[70] flex items-center justify-center p-4"><button type="button" aria-label="Close dialog" onClick={onClose} className="absolute inset-0 bg-black/50" /><div role="dialog" aria-modal="true" className="relative z-10 max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-lg border border-outline-variant bg-surface-container p-5 shadow-xl"><header className="mb-4 flex items-center justify-between"><h2 className="text-headline-sm font-bold text-on-surface">{title}</h2><button type="button" onClick={onClose} className={iconButtonClass()}><span className="material-symbols-outlined text-[18px]">close</span></button></header>{children}</div></div>; }
function Labels({ labels }: { labels: TaskLabelDto[] }) { return labels.length ? <div className="mt-3 flex flex-wrap gap-1">{labels.map((l) => <span key={l.id} className="rounded-full px-2 py-0.5 text-label-sm font-medium text-white" style={{ backgroundColor: l.color }}>{l.name}</span>)}</div> : null; }
function Meta({ icon, text }: { icon: string; text: string }) { return <span className="flex min-w-0 items-center gap-1"><span className="material-symbols-outlined text-[16px]">{icon}</span><span className="truncate">{text}</span></span>; }
function statusTone(status: number): Parameters<typeof StatusBadge>[0]["tone"] { if (status === TaskIssueStatus.ChangesRequested) return "danger"; if (status === TaskIssueStatus.Approved || status === TaskIssueStatus.Done) return "success"; if (status === TaskIssueStatus.InReview) return "warning"; if (status === TaskIssueStatus.InProgress) return "primary"; return "neutral"; }
function initials(a: { displayName: string; email: string }) { const source = a.displayName || a.email; return source.split(" ").map((p) => p[0]).join("").slice(0, 2).toUpperCase(); }
function today() { const d = new Date(); d.setHours(0, 0, 0, 0); return d; }
function formatDueDate(value: string | null) { if (!value) return "No due date"; const date = new Date(value); return Number.isNaN(date.getTime()) ? "No due date" : new Intl.DateTimeFormat("en", { month: "short", day: "numeric", year: "numeric" }).format(date); }
function formatDateTime(value: string) { const date = new Date(value); return Number.isNaN(date.getTime()) ? "" : new Intl.DateTimeFormat("en", { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" }).format(date); }
function dateInput(value: string | null) { return value ? value.slice(0, 10) : ""; }
function addMonths(value: Date, amount: number) { const next = new Date(value); next.setMonth(next.getMonth() + amount, 1); return next; }
function calendarDays(month: Date) { const start = new Date(month.getFullYear(), month.getMonth(), 1); start.setDate(start.getDate() - start.getDay()); return Array.from({ length: 42 }, (_, index) => { const day = new Date(start); day.setDate(start.getDate() + index); return day; }); }
function toDateInput(value: Date) { const year = value.getFullYear(); const month = String(value.getMonth() + 1).padStart(2, "0"); const day = String(value.getDate()).padStart(2, "0"); return `${year}-${month}-${day}`; }
function normalizeHex(value: string, fallback = "#5B6CFF") { const text = value.trim(); const withHash = text.startsWith("#") ? text : `#${text}`; return /^#[0-9a-fA-F]{6}$/.test(withHash) ? withHash.toUpperCase() : fallback; }
function textareaClass(extra = "") { return `w-full rounded-lg border border-outline-variant bg-surface-container-high px-3 py-2 text-body-sm text-on-surface focus:border-primary focus:outline-none ${extra}`; }
function secondaryButtonClass(extra = "") { return `inline-flex items-center gap-1.5 rounded-lg border border-outline-variant bg-surface-container-high px-3 py-2 text-label-md font-medium text-on-surface transition-colors hover:bg-surface-container ${extra}`; }
function dangerButtonClass(extra = "") { return `inline-flex items-center gap-1.5 rounded-lg bg-error px-3 py-2 text-label-md font-medium text-on-error transition-colors hover:bg-error/90 ${extra}`; }
function iconButtonClass(extra = "") { return `inline-flex h-8 w-8 items-center justify-center rounded-lg text-on-surface-variant transition-colors hover:bg-surface-container-high hover:text-on-surface ${extra}`; }
